// cl: /DNDEBUG /DWIN32 /MD /EHsc
//
// Retail 0x0017DD40 refuses to act until the logic frame reaches the deadline
// at +0x24, then clears one object status bit. The callee is the ILT 0x000307E7
// thunk that reverse/symbols.csv names Object::setStatus over a BitFlags<86>.
// The host class name is address-derived because no vtable slot or named caller
// reaches the body.

extern "C" void *__cdecl memset( void *dest, int value, unsigned int count );

template <int N>
class BitFlags
{
public:
	unsigned int m_bfmeWords[ 3 ];
};

class GameLogic
{
public:
	unsigned char m_bfmePad000[ 0x3c ];
	unsigned int m_bfmeFrame;
};

extern GameLogic *TheBfmeGameLogic;

class Object
{
public:
	void setStatus( const BitFlags<86> &flags, bool set );
};

class Rva0017DD40Host
{
public:
	int expire();

private:
	unsigned char m_bfmePad000[ 0x10 ];
	Object *m_bfmeInner;
	unsigned char m_bfmePad014[ 8 ];
	Rva0017DD40Host *m_bfmeOwner;
	unsigned char m_bfmePad020[ 4 ];
	unsigned int m_bfmeDeadline;
};

int Rva0017DD40Host::expire()
{
	if( m_bfmeDeadline < TheBfmeGameLogic->m_bfmeFrame )
		return -1;

	Object *obj = m_bfmeOwner->m_bfmeInner;

	BitFlags<86> flags;

	memset( flags.m_bfmeWords, 0, 12 );
	flags.m_bfmeWords[ 0 ] |= 0x400000;

	obj->setStatus( flags, false );

	return 0;
}
